package net.civeira.phylax.feature.access.userwebauthncredential.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.userwebauthncredential.domain.UserWebauthnCredential;
import net.civeira.phylax.feature.access.userwebauthncredential.domain.valueobject.SignCountVO;

class SignCountValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of sign count of user webauthn credential")
  void test_sign_count_value_holder_assign_plain_value() {
    Object holder = new Object();
    SignCountValueHolder<Object> value = new SignCountValueHolder<>(holder);
    Assertions.assertSame(holder, value.signCount(1), "Setters must return the holder");
    Assertions.assertTrue(value.getSignCountValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getSignCount().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of sign count of user webauthn credential")
  void test_sign_count_value_holder_assign_value_object() {
    Object holder = new Object();
    SignCountValueHolder<Object> value = new SignCountValueHolder<>(holder);
    SignCountVO vo = SignCountVO.from(1);
    Assertions.assertFalse(value.getSignCountValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.signCount(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSignCountValue().orElseThrow());
    Assertions.assertSame(holder, value.signCount(Optional.empty()));
    Assertions.assertFalse(value.getSignCountValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.signCount(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSignCountValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of sign count of user webauthn credential against the original")
  void test_sign_count_value_holder_read() {
    Object holder = new Object();
    SignCountValueHolder<Object> value = new SignCountValueHolder<>(holder);
    SignCountVO vo = SignCountVO.from(1);
    SignCountVO other = SignCountVO.from(1);
    UserWebauthnCredential original = Mockito.mock(UserWebauthnCredential.class);
    Mockito.when(original.getSignCountValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSignCount(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readSignCount(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.signCount(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSignCount(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSignCount(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of sign count of user webauthn credential")
  void test_sign_count_value_holder_unset() {
    Object holder = new Object();
    SignCountValueHolder<Object> value = new SignCountValueHolder<>(holder);
    SignCountVO vo = SignCountVO.from(1);
    value.signCount(vo);
    Assertions.assertSame(holder, value.unsetSignCountIfMatches("signCount_other"));
    Assertions.assertTrue(value.getSignCountValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSignCountIfMatches("signCount"));
    Assertions.assertFalse(value.getSignCountValue().isPresent(),
        "The field name must clear the value");
    value.signCount(vo);
    Assertions.assertSame(holder, value.unsetSignCount());
    Assertions.assertFalse(value.getSignCountValue().isPresent(), "Unset must clear the value");
  }
}
